typedef struct _SENSOR_LOCATION {

  ESENSOR_LOCATION eSensorLocation;
  ESENSOR_LOCATION eSensorLocation2;    // secondary specification for sensor, i.e. VRM for GPU (primary location)
  int iLocationIndex;                   // index of sensor (i.e. CPU#0, GPU#2)
  char szLocationName[SENSOR_MAX_STRING_LEN];  // name of sensor (i.e. "Intel Core...")
  char szLocationName2[SENSOR_MAX_STRING_LEN];  // secondary name of sensor (i.e. discrete sensor name on a GPU)

} SENSOR_LOCATION, *PSENSOR_LOCATION;

typedef struct _READING_LOCATION {

  EREADING_LOCATION eReadingLocation;
  int iLocationIndex;                  // main index of reading (i.e. Core#0)
  int iLocationIndex2;                 // 2nd  index of reading (i.e. Core#n, Thread#1)
  char szLocationName[SENSOR_MAX_STRING_LEN];  // reading name

} READING_LOCATION, *PREADING_LOCATION;

enum ETEMPERATURE_TYPE {
  TEMPERATURE_ABS=0,          // Absolute temperature value in degrees Celsius
  TEMPERATURE_OFFSET,         // Temperature relative to maximum value (i.e. to Tj,max)
  TEMPERATURE_CTL             // Tctl on AMD CPUs (not real temperature)
};

enum EVOLTAGE_TYPE {
  VOLTAGE_ABS=0,              // Absolute voltage value in Volts
  VOLTAGE_OFFSET,             // Voltage offset (i.e. Uncore voltage offset)
  VOLTAGE_VID,                // Voltage ID (VID) - voltage set (requested to VRM)
};

enum EFAN_TYPE {
  FAN_STANDARD=0,             // Fan speed in RPM
  FAN_PERCENT,                // Fan speed in percent
  FAN_DUTY,                   // Fan duty cycle in percent
  FAN_PUMP,                   // Pump (water pump, etc.)
  FAN_LC                      // Liquid Cooling
};

enum ECURRENT_TYPE {
  CURRENT_CONSUMPTION=0       // Current consumption in Amperes
};

enum EPOWER_TYPE {
  POWER_CONSUMPTION=0,        // Power consumption in Watts
  POWER_CONSUMPTION_PERC,     // Power consumption in % of TDP power
  POWER_CONSUMPTION_NORM,     // Power consumption in % normalized to current limit
  POWER_LIMIT,                // Power limit in Watts
};

enum ECLOCK_TYPE {
  CLOCK_FREQUENCY=0,          // Actual Frequency in MHz
  CLOCK_EFFECTIVE             // Effective clock (for CPUs counts only cycles when not sleeping)
};

enum EUSAGE_TYPE {
  USAGE_UTILIZATION,        // Resource utilization (i.e. CPU usage, GPU utilization)
  USAGE_UTILIZATION_AVG,    // Average resource utilization (i.e. Total CPU usage - average of all threads)
  USAGE_STATE_RESIDENCY,    // State residency in % (i.e. C0 State Residency)
  USAGE_CLOCK_MODULATION,   // Clock Modulation (Duty cycles)
  USAGE_ACTIVITY_READ,      // Device Read activity in %
  USAGE_ACTIVITY_WRITE,     // Device Write activity in %
  USAGE_ACTIVITY_TOTAL,     // Device Total activity (Read+Write) in %
  USAGE_CHARGE_LEVEL,       // Charge Level [%]
  USAGE_HEALTH              // Device health
};

enum EOTHER_TYPE {
  OTHER_BOOLEAN=0,          // General Boolean value (0=false, 1=true)
  OTHER_CLOCK_RATIO,        // Clock ratio to reference (bus) clock
  OTHER_MEMORY_USED,        // Amount of Memory used/committed in MBytes
  OTHER_MEMORY_FREE,        // Amount of Memory available in MBytes
  OTHER_MEMORY_LOAD,        // Percentage of Memory utilization (used / total)
  OTHER_MEMORY_TIMING,      // Memory Timing parameter [T]
  OTHER_TEMP_THROTTLING,    // Boolean value determining if throttling is active
  OTHER_TEMP_CRITICAL,      // Boolean value determining if critical temperature is reached
  OTHER_POWER_LIMITING,     // Boolean value determining if power limit is reached
  OTHER_PERF_LIMITING,      // Boolean value determining reason for performance limiting
  OTHER_SPEED_GTS,          // Transfer speed in GT/s
  OTHER_SPEED_GBPS,         // Transfer speed in Gbps
  OTHER_PRESSURE,           // Pressure in bar
  OTHER_FLOW,               // Water flow in L/h
  OTHER_FLOW_LM,            // Water flow in L/m
  OTHER_EFFICIENCY,         // Efficiency in %
  OTHER_ERROR_COUNT,        // Number of Errors
  OTHER_FAILURE,            // Boolean value determining if device reports a failure
  OTHER_WARNING,            // Boolean value determining if device reports a warning
  OTHER_DATA_WRITTEN,       // Amount of data written in Gigabytes; for network download amount MBytes
  OTHER_DATA_READ,          // Amount of data written in Gigabytes; for network upload amount MBytes
  OTHER_RATE_READ,          // Device read rate in MBytes/s; for network download rate in KB/s
  OTHER_RATE_WRITE,         // Device write rate in MBytes/s; for network upload rate in KB/s
  OTHER_INTRUSION,          // Boolean value determining intrusion status
  OTHER_FREQUENCY,          // Frequency in Hz
  OTHER_FPS,                // Frames Per Second
  OTHER_AC_RATING,          // Power Rating of AC Adapter; 0=Not Plugged-in, 1=Unknown, others: rating in Watts

  OTHER_CAPACITY,           // Remaining Capacity [Wh]
  OTHER_CHARGE_LEVEL,       // Charge Level [%]
  OTHER_CHARGE_RATE,        // Charge Rate [W]
  OTHER_WEAR_LEVEL,         // Wear Level [%]
  OTHER_REM_TIME,           // Remaining Time [minutes]

  // Cx-state residency counters:
  // iLocationIndex specifies Core number, iLocationIndex2 specifies Thread number, -1 means all cores/threads
  OTHER_C0_RESIDENCY,       // C0-State residency in %
  OTHER_C1_RESIDENCY,       // C1-State residency in %
  OTHER_C2_RESIDENCY,       // C2-State residency in %
  OTHER_C3_RESIDENCY,       // C3-State residency in %
  OTHER_C4_RESIDENCY,       // C4-State residency in %
  OTHER_C5_RESIDENCY,       // C5-State residency in %
  OTHER_C6_RESIDENCY,       // C6-State residency in %
  OTHER_C7_RESIDENCY,       // C7-State residency in %
  OTHER_C8_RESIDENCY,       // C8-State residency in %
  OTHER_C9_RESIDENCY,       // C9-State residency in %
  OTHER_C10_RESIDENCY,      // C10-State residency in %

  OTHER_NOISE,              // Noise [dB]
  OTHER_WATER_LEAK,         // Water Leak detection (0=false, 1=true)
  OTHER_VOLUME,             // Volume [ml]

  OTHER_ENERGY_KWH,         // Energy [kWh]

  OTHER_UPTIME_M,           // Uptime [minutes]
  OTHER_UPTIME_H,           // Uptime [hours]
  OTHER_UPTIME_D            // Uptime [days]
};

enum EREADING_TYPE {
  READING_NONE=0,
  READING_TEMP,
  READING_VOLT,
  READING_FAN,
  READING_CURRENT,
  READING_POWER,
  READING_CLOCK,
  READING_USAGE,
  READING_OTHER
};

typedef struct _READING_TYPE {

  EREADING_TYPE eType;
  union {
    ETEMPERATURE_TYPE eTempType;
    EVOLTAGE_TYPE eVoltType;
    EFAN_TYPE eFanType;
    ECURRENT_TYPE eCurrentType;
    EPOWER_TYPE ePowerType;
    ECLOCK_TYPE eClockType;
    EUSAGE_TYPE eUsageType;
    EOTHER_TYPE eOtherType;
  };
  
} READING_TYPE, *PREADING_TYPE;

typedef struct _SENSOR_INFO {

  SENSOR_LOCATION  tSensorLocation;   // Specifies the main location of sensor (CPU, GPU, DISK, etc.)
  READING_LOCATION tReadingLocation;  // Specifies the location of reading within the sensor (CPU Core0, ...)
  READING_TYPE tReadingType;          // Specifies details about the reading (Temperature/absolute, ...)

} SENSOR_INFO, *PSENSOR_INFO;

typedef struct _SENSOR_READ_RESULT {

  BOOL IsValid;                       // Determines if this returns a valid sensor value
  double value;                       // Actual sensor value read
  char szUnits[32];                   // String describing value units
  SENSOR_INFO tSensorInfo;            // Provides information about sensor location and type

} SENSOR_READ_RESULT, *PSENSOR_READ_RESULT;

//#pragma pack(pop)


#endif
